SELECT * FROM pet
WHERE adopt_status = 2

    AND species = #{species}


    AND breed LIKE CONCAT('%', #{breed}, '%')


    AND gender = #{gender}


    AND age_stage = #{ageStage}


    AND is_neutered = #{isNeutered}


    AND is_vaccinated = #{isVaccinated}

ORDER BY create_time DESC

